/**
 *
 * Reldens - Test Maps Wizard Import
 *
 * Tests the maps wizard import of the selected generated maps against the test database: the sample maps generated by
 * the "multiple by loader" strategy (MapsWizardBaseTest) are imported with the data of the maps selection page and two
 * of the three maps selected, through the SelectedMapsImportRunner with a real MapsImporter on a theme folder in
 * test-results; only the selected maps become rooms, disabled, with the titles typed on the page, their map file and
 * their map image, each with one return point read from its map (its default return point marker is lost, ISSUE #405,
 * so the return point values are not checked), their JSON and image are copied to the theme and dist maps folders,
 * and the import redirects to the view of the first imported room. The imported rooms are deleted after the test.
 *
 */

const { MapsWizardBaseTest } = require('./fixtures/maps-wizard-base-test');
const { Utils } = require('./utils');
const { MapsImporter } = require('../lib/import/server/maps-importer');
const { SelectedMapsImportRunner } = require('../lib/admin/server/selected-maps-import-runner');
const { FileHandler } = require('@reldens/server-utils');
const { sc } = require('@reldens/utils');

class TestMapsWizardImport extends MapsWizardBaseTest
{

    constructor(config)
    {
        super(config, 'maps-wizard-import');
        this.isIntegration = true;
        this.importThemeManager = Object.assign({}, this.themeManager, {projectRoot: this.testFolder});
    }

    async deleteImportedRooms(dataServer, roomNames)
    {
        for(let roomName of roomNames){
            let room = await dataServer.getEntity('rooms').loadOneBy('name', roomName);
            if(!room){
                continue;
            }
            await dataServer.getEntity('roomsChangePoints').delete({room_id: room.id});
            await dataServer.getEntity('roomsReturnPoints').delete({room_id: room.id});
            await dataServer.getEntity('rooms').deleteById(room.id);
        }
    }

    async importSelectedMaps(dataServer, pageData, mapsTitles)
    {
        let config = {get: (path, defaultValue) => defaultValue, getWithoutLogs: (path, defaultValue) => defaultValue};
        let body = {
            mainAction: 'import',
            tilesetSessionId: '',
            selectedMaps: Object.keys(mapsTitles),
            generatedMapsHandler: pageData.generatedMapsHandler,
            importAssociationsForChangePoints: pageData.importAssociationsForChangePoints,
            importAssociationsRecursively: pageData.importAssociationsRecursively,
            verifyTilesetImage: pageData.verifyTilesetImage,
            automaticallyExtrudeMaps: pageData.automaticallyExtrudeMaps,
            handlerParams: pageData.handlerParams
        };
        for(let mapName of Object.keys(mapsTitles)){
            body['map-title-'+mapName] = mapsTitles[mapName];
        }
        return await new SelectedMapsImportRunner(
            new MapsImporter({configManager: config, dataServer, themeManager: this.importThemeManager}),
            {clearBackups: () => true}
        ).run({body}, {rootPath: '/reldens-admin', viewPath: '/view', mapsWizardPath: '/maps-wizard'});
    }

    async loadImportedRoom(dataServer, roomName)
    {
        let room = await dataServer.getEntity('rooms').loadOneBy('name', roomName);
        if(!room){
            return false;
        }
        return {
            id: room.id,
            name: room.name,
            title: room.title,
            map_filename: room.map_filename,
            scene_images: room.scene_images,
            customData: room.customData,
            changePoints: (await dataServer.getEntity('roomsChangePoints').loadBy('room_id', room.id)).length,
            returnPoints: (await dataServer.getEntity('roomsReturnPoints').loadBy('room_id', room.id)).length
        };
    }

    async testTheSelectedGeneratedMapsAreImportedAsRooms()
    {
        await this.test('only the selected generated maps are imported as disabled rooms with their files', async () => {
            let dataServer = Utils.createDataServer(this.config);
            await dataServer.connect();
            dataServer.generateEntities();
            let generation = await this.generateSampleMaps('multiple-by-loader', 'map-composite-data-with-names.json');
            let pageData = generation.rendered[0];
            let selectedPreviews = pageData.maps.slice(0, 2);
            let mapsTitles = {[selectedPreviews[0].key]: 'Imported Map One', [selectedPreviews[1].key]: 'Imported Map Two'};
            await this.deleteImportedRooms(dataServer, pageData.maps.map(preview => preview.key));
            let redirect = await this.importSelectedMaps(dataServer, pageData, mapsTitles);
            let importedRooms = [];
            for(let preview of selectedPreviews){
                importedRooms.push(await this.loadImportedRoom(dataServer, preview.key));
            }
            let notSelectedRoom = await dataServer.getEntity('rooms').loadOneBy('name', pageData.maps[2].key);
            let copiedFiles = this.runtimeMapsFolders.map(mapsFolder => FileHandler.readFolder(mapsFolder));
            await this.deleteImportedRooms(dataServer, Object.keys(mapsTitles));
            FileHandler.remove(this.testFolder);
            this.assert.deepStrictEqual(
                importedRooms.map(importedRoom => importedRoom && Object.assign({}, importedRoom, {id: 0})),
                selectedPreviews.map(preview => ({
                    id: 0,
                    name: preview.key,
                    title: mapsTitles[preview.key],
                    map_filename: preview.key+'.json',
                    scene_images: preview.mapImage.split('/').pop(),
                    customData: sc.toJsonString({enabled: false}),
                    changePoints: 0,
                    returnPoints: 1
                }))
            );
            let expectedFiles = selectedPreviews.flatMap(preview => [preview.key+'.json', preview.mapImage.split('/').pop()]);
            this.assert.deepStrictEqual(
                [redirect, notSelectedRoom, copiedFiles],
                ['/reldens-admin/rooms/view?id='+importedRooms[0].id+'&result=success', null, [expectedFiles, expectedFiles]]
            );
        });
    }

}

module.exports.TestMapsWizardImport = TestMapsWizardImport;
